  ('a47d598c-9450-56a8-97d7-02c55e8fcda5', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'medium',
   $q$Read the sentences: "The glider circled over the valley. Its wings caught the warm updrafts." Which choice combines them correctly using an absolute phrase?$q$, $q$[{"text":"Its wings catching the warm updrafts, the glider circled over the valley.","is_correct":true},{"text":"Catching the warm updrafts, the glider circled over the valley.","is_correct":false,"misconception_token":"participial-not-absolute"},{"text":"The glider circled over the valley, its wings caught the warm updrafts.","is_correct":false,"misconception_token":"comma-splice"},{"text":"Because its wings caught the warm updrafts, the glider circled over the valley.","is_correct":false,"misconception_token":"adverbial-clause-not-absolute"}]$q$::jsonb, $q$Its wings catching the warm updrafts, the glider circled over the valley.$q$, $q$"Its wings catching the warm updrafts" pairs a noun with a participle and has no complete verb, so it is an absolute phrase. "Catching the warm updrafts" is a correct sentence, but it uses a participial phrase, not an absolute phrase.$q$, 'draft', null)
