  ('2055bf96-52d7-558e-9198-949bf6f2a17f', null, (select id from public.skills where slug = 'write-g10-grammar-usage'), null, 'medium',
   $q$Only the tomatoes that ripened early were sent to the farmers market; the rest stayed on the vines. Which sentence uses a clause to express this meaning?$q$, $q$[{"text":"The tomatoes that ripened early went to the farmers market.","is_correct":true},{"text":"The tomatoes, which ripened early, went to the farmers market.","is_correct":false,"misconception_token":"nonrestrictive-implies-all"},{"text":"Ripening early, the farmers market received the tomatoes.","is_correct":false,"misconception_token":"dangling-modifier"},{"text":"The tomatoes went to the farmers market, which ripened early.","is_correct":false,"misconception_token":"misplaced-relative-clause"}]$q$::jsonb, $q$The tomatoes that ripened early went to the farmers market.$q$, $q$The restrictive clause "that ripened early" narrows the group to only the early tomatoes. Setting the clause off with commas, as in "which ripened early," suggests that all of the tomatoes ripened early and all went to market.$q$, 'draft', null)
